// Regression tests for the build-pipeline staleness defect (W5-I).
//
// THE DEFECT. Three subtrees are generated by `npm run build` and copied into
// app.asar by electron-builder.yml. Nothing compared them against the current
// sources, so a skipped, interrupted or incrementally short-circuited build shipped
// whatever was left behind. Measured on this tree before the fix:
//   * build/gateway/server.mjs was 161,217 B while a clean bundle is 163,151 B and
//     did not contain "no reasoning output observed" (src/gateway/capability-probe.mjs:693).
//   * build/renderer had no `endpoint_creds_error` (src/renderer/i18n/resources.ts:142)
//     in any of the 7 locales.
// Both shipped. These tests exist so the guard cannot be removed or hollowed out.
//
// The audit that followed found FOUR more holes, each covered below:
//   1. `--root` was a lie for the gateway subtree: emitGateway dropped the root and
//      buildGatewayBundle resolved its own, so a --root audit bundled THIS repo.
//   2. build/release-notes.md is generated and ships (latest.yml + GitHub body) but
//      was compared against nothing.
//   3. app.asar — what the user actually runs — was never compared against build/.
//   4. the tsc reference emit returned `src` without asserting the layout, so a
//      tsconfig rootDir/include change would produce mass "missing" (false positive)
//      or a silent exclusion instead of a clear toolchain error.

import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { pathToFileURL } from 'node:url';
import { createRequire } from 'node:module';
import yaml from 'js-yaml';

const root = path.resolve(import.meta.dirname, '..');
const cleanScript = path.join(root, 'scripts', 'clean-node-build.mjs');
const verifyScript = path.join(root, 'scripts', 'verify-build-freshness.mjs');
const bundleScript = path.join(root, 'scripts', 'build-gateway-bundle.mjs');
const packageJson = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));

/**
 * Scratch space for a test run. os.tmpdir() rather than a repo path on purpose:
 * the mutation proofs COPY real artifacts and then damage them, and a test must
 * never be able to reach the real build/ tree even by accident.
 */
function sandbox(t) {
  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'nvgw-w5i-'));
  t.after(() => fs.rmSync(directory, { recursive: true, force: true }));
  return directory;
}

// ── 1. The clean step covers every generated, shipped directory ─────────────

test('clean-node-build removes build/renderer and every *.tsbuildinfo, and keeps committed assets', async (t) => {
  const directory = sandbox(t);
  // A file:// URL, not a bare path: on Windows the ESM loader rejects a drive-letter
  // specifier with ERR_UNSUPPORTED_ESM_URL_SCHEME.
  const { cleanNodeBuild, CLEANED_PATHS } = await import(pathToFileURL(cleanScript).href);

  // One file in every generated location the build writes, plus the two things
  // that must SURVIVE a clean.
  const generated = [
    'build/src/main/index.js',
    'build/src/preload/index.js',
    'build/src/test-support/legacy-nvidia-migration.js',
    'build/src/renderer/lib/frontend-behavior.js',
    'build/gateway/server.mjs',
    'build/renderer/index.html',
    'build/renderer/assets/index-COaZSDF5.js',
    'build/tsconfig.node.tsbuildinfo',
    'nested/project/tsconfig.tsbuildinfo'
  ];
  const survivors = [
    'build/assets/icon.png',
    'build/installer.nsh',
    // Never descended into: these are dependency trees, not build output.
    'node_modules/some-dep/index.tsbuildinfo',
    'dist/win-unpacked/stale.tsbuildinfo'
  ];
  for (const relative of [...generated, ...survivors]) {
    const absolute = path.join(directory, ...relative.split('/'));
    fs.mkdirSync(path.dirname(absolute), { recursive: true });
    fs.writeFileSync(absolute, 'fixture', 'utf8');
  }

  const report = cleanNodeBuild({ root: directory });

  for (const relative of generated) {
    assert.equal(fs.existsSync(path.join(directory, ...relative.split('/'))), false,
      `clean-node-build must remove ${relative}`);
  }
  for (const relative of survivors) {
    assert.equal(fs.existsSync(path.join(directory, ...relative.split('/'))), true,
      `clean-node-build must NOT remove ${relative}`);
  }

  // build/renderer is the specific omission this defect came from: it ships and it
  // was not in the cleaned set, so a stale vite emit survived every rebuild.
  assert.ok(CLEANED_PATHS.includes('build/renderer'),
    'build/renderer must be in the cleaned set — it ships via electron-builder.yml');
  assert.ok(CLEANED_PATHS.includes('build/gateway'));
  assert.ok(report.removedBuildInfo.length >= 2,
    'every *.tsbuildinfo outside node_modules/.git/dist must be reported as removed');
});

test('the clean step is wired to prebuild, so no npm build can start from incremental state', () => {
  assert.equal(packageJson.scripts.prebuild, 'node scripts/clean-node-build.mjs',
    'prebuild must run the clean step');
  assert.equal(packageJson.scripts.postbuild, 'node scripts/verify-build-freshness.mjs',
    'postbuild must assert emit equality, so `npm run build` cannot exit 0 with stale artifacts');
});

test('the clean-step comment does not claim it covers tsc root outputs it leaves alone', () => {
  // The comment used to say "every directory build WRITES". build/vite.config.js and
  // build/vite.config.d.ts ARE written by the same tsc run but are neither cleaned
  // nor verified; they do not ship, so the code is right and the comment was wrong.
  // A comment that overstates coverage is how the next reader concludes a hole is
  // covered, so the inaccuracy is pinned here.
  const source = fs.readFileSync(cleanScript, 'utf8');
  assert.doesNotMatch(source, /Every directory `npm run build` WRITES/,
    'the comment must not claim the list is every directory the build writes');
  assert.match(source, /NOT a complete list of what tsc writes/,
    'the comment must say the tsc root outputs are outside this list');
  assert.match(source, /vite\.config\.(js|d\.ts)/,
    'the comment must name the tsc root outputs it does not cover');
});

// ── 2. CI runs the verifier after the build, and the asar check after packaging ─

test('test.yml verifies build freshness inside the packaged-audit job, after the build', () => {
  const workflow = yaml.load(fs.readFileSync(path.join(root, '.github', 'workflows', 'test.yml'), 'utf8'));
  const job = workflow.jobs?.['packaged-audit'];
  assert.ok(job, 'the packaged-audit job must exist');

  const steps = job.steps ?? [];
  const runs = (step, pattern) => typeof step.run === 'string' && pattern.test(step.run);
  const buildIndex = steps.findIndex((step) => runs(step, /npm run package:dir|npm run build\b/));
  const verifyIndex = steps.findIndex((step) => runs(step, /verify:build-freshness|verify-build-freshness\.mjs/));

  assert.ok(buildIndex >= 0, 'the job must build before anything is audited');
  assert.ok(verifyIndex >= 0, 'the packaged-audit job must run the freshness verifier');
  assert.ok(verifyIndex > buildIndex,
    'the freshness verifier must run AFTER the build, otherwise it audits the previous artifact');

  // Defect 3: the archive the user RUNS must be compared against build/, and only
  // after it was produced. Without this step a stale app.asar ships green.
  const asarIndex = steps.findIndex((step) => runs(step, /verify:asar|verify-build-freshness\.mjs\s+--asar/));
  assert.ok(asarIndex >= 0, 'the job must run the packaged-asar freshness check');
  assert.ok(asarIndex > buildIndex,
    'the asar check must run AFTER package:dir, otherwise it reads a previous archive');
  assert.equal(packageJson.scripts['verify:asar'], 'node scripts/verify-build-freshness.mjs --asar',
    'the CI step and the local command must be the same command');
});

test('test.yml ARMS the notes gate: generates the file first and passes --require-release-notes', () => {
  // THE DEFECT: `--require-release-notes` appeared in NO workflow, and the only
  // `node scripts/release-notes.mjs` in the job sat at the very END (inside the nsis
  // smoke), after both verify steps. On a clean runner the gitignored file is absent,
  // so the verifier printed BUILD_FRESHNESS_UNCHECKED and exited 0: the notes half of
  // the gate was structurally unarmed in CI while looking present in the workflow.
  const workflow = yaml.load(fs.readFileSync(path.join(root, '.github', 'workflows', 'test.yml'), 'utf8'));
  const job = workflow.jobs?.['packaged-audit'];
  assert.ok(job, 'the packaged-audit job must exist');
  const steps = job.steps ?? [];
  const runs = (step, pattern) => typeof step.run === 'string' && pattern.test(step.run);

  const generateIndex = steps.findIndex((step) => runs(step, /node scripts\/release-notes\.mjs/));
  const verifyIndex = steps.findIndex((step) => runs(step, /verify:build-freshness/));
  const asarIndex = steps.findIndex((step) => runs(step, /verify:asar/));
  assert.ok(generateIndex >= 0, 'the job must GENERATE build/release-notes.md');
  assert.ok(verifyIndex >= 0, 'the job must run the freshness verifier');
  assert.ok(generateIndex < verifyIndex,
    'the notes must be generated BEFORE the verifier reads them, or the gate judges a file it never produced');
  assert.ok(asarIndex < 0 || generateIndex < asarIndex,
    'the notes must also exist before the asar step, so the whole job sees one notes state');

  // The flag is what converts "absent" into a failure; without it the gate is a print.
  const verifyStep = steps[verifyIndex];
  assert.match(verifyStep.run, /verify:build-freshness\s+--\s+--require-release-notes/,
    'the verify step must pass --require-release-notes through npm, or a missing/tampered file still exits 0');
  assert.match(String(verifyStep.name ?? ''), /fresh/i, 'the step must still be identifiable as the freshness gate');
  // A generated-but-unchecked gate is the same hole one level down: the step must not
  // be neutralised by continue-on-error, and it must not be conditional.
  assert.equal(verifyStep['continue-on-error'], undefined, 'the freshness gate must not be allowed to fail softly');
  assert.equal(verifyStep.if, undefined, 'the freshness gate must run unconditionally');
});

test('regression proof: the pre-fix workflow shape is rejected by the notes-gate detector', () => {
  // The exact shape that shipped: no generation step before the verifier, and the
  // verifier called without the flag. A detector that accepted this would let the
  // defect back in with every test green.
  const armed = (steps) => {
    const runs = (step, pattern) => typeof step.run === 'string' && pattern.test(step.run);
    const generateIndex = steps.findIndex((step) => runs(step, /node scripts\/release-notes\.mjs/));
    const verifyIndex = steps.findIndex((step) => runs(step, /verify:build-freshness/));
    if (generateIndex < 0 || verifyIndex < 0 || generateIndex > verifyIndex) return false;
    return /verify:build-freshness\s+--\s+--require-release-notes/.test(steps[verifyIndex].run);
  };
  const verifier = { run: 'npm run verify:build-freshness' };
  const armedVerifier = { run: 'npm run verify:build-freshness -- --require-release-notes' };
  const generator = { run: 'node scripts/release-notes.mjs' };

  assert.equal(armed([verifier]), false, 'no generation and no flag is the pre-fix hole');
  assert.equal(armed([verifier, generator]), false, 'generating AFTER the verifier judges a file that did not exist');
  assert.equal(armed([generator, verifier]), false, 'generating before is not enough while the flag is missing');
  assert.equal(armed([armedVerifier, generator]), false, 'the flag alone does not replace generating first');
  assert.equal(armed([generator, armedVerifier]), true, 'generate-then-require is the armed shape');
});

// ── 3. The verifier passes on the real, freshly built tree ─────────────────

test('the shipped subtrees on disk are byte-identical to a clean emit', { timeout: 300_000 }, () => {
  // This is the same command CI runs. It re-emits build/src (tsc), build/renderer
  // (vite) and build/gateway (esbuild) into a throwaway directory and compares.
  const result = spawnSync(process.execPath, [verifyScript], { cwd: root, encoding: 'utf8' });
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;
  assert.equal(result.status, 0, `verify-build-freshness must exit 0 on a fresh build:\n${output}`);
  for (const subtree of ['build/src', 'build/gateway', 'build/renderer']) {
    assert.match(output, new RegExp(`BUILD_FRESHNESS_VERIFIED ${subtree.replace('/', '\\/')} `),
      `${subtree} must be reported as verified:\n${output}`);
  }
  assert.match(output, /BUILD_FRESHNESS_OK 3\/3/);
  // Defect 2: the generated notes file is part of the same verdict, not a silent
  // extra. On a clean clone it does not exist (gitignored) and is reported UNCHECKED;
  // when it exists it is either VERIFIED or a STALE_BUILD_ARTIFACT that fails the run.
  assert.match(output, /BUILD_FRESHNESS_(VERIFIED|UNCHECKED) build\/release-notes\.md/,
    `the release-notes verdict must always be printed:\n${output}`);
});

// ── 4. Mutation proofs: the verifier has teeth, per subtree ────────────────

/**
 * Copy one real subtree into the sandbox, damage it, and require the verifier to
 * name it. The real build/ tree is only ever READ here: its aggregate hash is
 * captured before the proof and compared after, so a mutation that escaped the
 * sandbox would be caught rather than silently corrupting the tree under test.
 */
function proveDetection(t, { subtree, mutate }) {
  const directory = sandbox(t);
  const copyRoot = path.join(directory, 'artifact');
  const relative = subtree.split('/');
  const realSubtree = path.join(root, ...relative);
  const realBefore = treeHash(realSubtree);
  fs.cpSync(realSubtree, path.join(copyRoot, ...relative), { recursive: true });

  const damage = mutate(path.join(copyRoot, ...relative));
  assert.ok(damage, 'each mutation must actually change the copy');

  const result = spawnSync(process.execPath, [
    verifyScript,
    '--subtree', subtree,
    '--artifact-root', copyRoot,
    '--work-dir', path.join(directory, 'work')
  ], { cwd: root, encoding: 'utf8' });
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;

  assert.equal(result.status, 1,
    `a damaged ${subtree} must fail the verifier with exit 1:\n${output}`);
  assert.ok(output.includes(`STALE_BUILD_ARTIFACT ${subtree}`),
    `the failure must name the stale subtree:\n${output}`);
  assert.ok(output.includes(damage),
    `the failure must name the offending file ${damage}:\n${output}`);
  assert.ok(output.includes('BUILD_FRESHNESS_FAILED'),
    `the failure must carry the machine-readable verdict:\n${output}`);
  // And the REAL tree must be untouched by the proof.
  assert.equal(treeHash(realSubtree), realBefore,
    'the mutation proof must never modify the real build/ tree');
}

/** Aggregate SHA-256 over `<relative path> NUL <sha256>` for every file in a tree. */
function treeHash(directory) {
  const aggregate = crypto.createHash('sha256');
  const walk = (relative = '') => {
    const entries = fs.readdirSync(path.join(directory, relative), { withFileTypes: true })
      .sort((left, right) => left.name.localeCompare(right.name));
    for (const entry of entries) {
      const next = relative ? `${relative}/${entry.name}` : entry.name;
      if (entry.isDirectory()) walk(next);
      else {
        const digest = crypto.createHash('sha256')
          .update(fs.readFileSync(path.join(directory, ...next.split('/')))).digest('hex');
        aggregate.update(`${next}\0${digest}\n`);
      }
    }
  };
  walk();
  return aggregate.digest('hex');
}

test('a tampered build/src file is detected', { timeout: 300_000 }, (t) => {
  proveDetection(t, {
    subtree: 'build/src',
    mutate: (directory) => {
      const relative = 'main/legacy-migration-exclusion.js';
      fs.appendFileSync(path.join(directory, ...relative.split('/')), '\n// stale\n', 'utf8');
      return relative;
    }
  });
});

test('a stale build/gateway bundle is detected', { timeout: 300_000 }, (t) => {
  proveDetection(t, {
    subtree: 'build/gateway',
    mutate: (directory) => {
      // The real defect: the shipped bundle was 1,934 B short of a clean emit.
      const file = path.join(directory, 'server.mjs');
      fs.writeFileSync(file, fs.readFileSync(file, 'utf8').replace('no reasoning output observed', 'stale'), 'utf8');
      return 'server.mjs';
    }
  });
});

test('a stale build/renderer emit (old hashed asset, missing new one) is detected', { timeout: 300_000 }, (t) => {
  proveDetection(t, {
    subtree: 'build/renderer',
    mutate: (directory) => {
      // Exactly the shipped failure shape: the previous content-hashed bundle
      // survives while the current one is absent.
      const assets = path.join(directory, 'assets');
      const bundle = fs.readdirSync(assets).find((name) => name.endsWith('.js'));
      assert.ok(bundle, 'the renderer copy must contain a JS bundle');
      fs.renameSync(path.join(assets, bundle), path.join(assets, 'index-BPrMadS9.js'));
      return 'assets/index-BPrMadS9.js';
    }
  });
});

// ── 4b. Defect 1: `--root` must actually be bundled from ───────────────────

/**
 * Build a throwaway root whose gateway entry is ONE line, so the emitted bundle is
 * unmistakably not this repository's 160 KB engine. package.json + CHANGELOG.md are
 * present because a real audited checkout always has them, and the notes check reads
 * them; the notes FILE itself is absent, which the verifier reports as UNCHECKED.
 */
function oneLineGatewayRoot(t) {
  const directory = sandbox(t);
  const gateway = path.join(directory, 'root', 'src', 'gateway');
  fs.mkdirSync(gateway, { recursive: true });
  fs.writeFileSync(path.join(gateway, 'server.mjs'), 'export const oneLine = true;\n', 'utf8');
  fs.writeFileSync(path.join(directory, 'root', 'package.json'),
    JSON.stringify({ name: 'probe', version: '0.0.0' }), 'utf8');
  fs.writeFileSync(path.join(directory, 'root', 'CHANGELOG.md'),
    '# Changelog\n\n## [0.0.0] - 2026-01-01\n\n- probe\n', 'utf8');
  return { directory, root: path.join(directory, 'root') };
}

test('buildGatewayBundle bundles the ROOT it is given, not this repository', { timeout: 120_000 }, async (t) => {
  // MEASURED BEFORE THE FIX: buildGatewayBundle({outputRoot}) ignored any root, so
  // this emitted the real 163,151 B engine from the repo. Every `--root` audit was
  // therefore comparing this repo against the copy and its verdict was meaningless.
  const { directory, root: fakeRoot } = oneLineGatewayRoot(t);
  const { buildGatewayBundle } = await import(pathToFileURL(bundleScript).href);
  const outputRoot = path.join(directory, 'out');

  const proof = await buildGatewayBundle({ root: fakeRoot, outputRoot });

  const emitted = fs.readFileSync(path.join(outputRoot, 'build', 'gateway', 'server.mjs'), 'utf8');
  assert.match(emitted, /oneLine/, 'the emitted bundle must come from the given root');
  assert.ok(Buffer.byteLength(emitted) < 1000,
    `a 1-line entry must not produce a ${Buffer.byteLength(emitted)} B bundle — the root was ignored`);
  assert.equal(proof.bundledModuleCount, 1, 'a 1-line entry bundles exactly one module');
});

test('a --root audit re-emits from that root, so a copy of THIS repo is reported stale', { timeout: 300_000 }, (t) => {
  // The end-to-end shape of the same defect: audit a copy of the real bundle while
  // pointing --root at a 1-line tree. The reference emit must be the 1-line bundle,
  // so the copy cannot be reported as fresh.
  const { directory, root: fakeRoot } = oneLineGatewayRoot(t);
  const artifact = path.join(directory, 'artifact', 'build', 'gateway');
  fs.mkdirSync(artifact, { recursive: true });
  fs.copyFileSync(path.join(root, 'build', 'gateway', 'server.mjs'), path.join(artifact, 'server.mjs'));

  const result = spawnSync(process.execPath, [
    verifyScript,
    '--subtree', 'build/gateway',
    '--root', fakeRoot,
    '--artifact-root', path.join(directory, 'artifact'),
    '--work-dir', path.join(directory, 'work')
  ], { cwd: root, encoding: 'utf8' });
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;

  assert.equal(result.status, 1, `a mismatched --root audit must exit 1:\n${output}`);
  assert.ok(output.includes('STALE_BUILD_ARTIFACT build/gateway'), output);
  // The decisive assertion: `fresh` is the 1-line emit, not the repository's engine.
  const freshSizes = [...output.matchAll(/fresh=(\d+) B/g)].map((match) => Number(match[1]));
  assert.ok(freshSizes.length > 0, `the report must print the fresh size:\n${output}`);
  assert.ok(freshSizes.every((size) => size < 1000),
    `the reference emit must be the 1-line bundle, got fresh sizes ${JSON.stringify(freshSizes)}:\n${output}`);
});

test('a --root with no gateway entry exits 2 instead of silently bundling this repo', { timeout: 120_000 }, (t) => {
  const directory = sandbox(t);
  fs.mkdirSync(path.join(directory, 'build', 'gateway'), { recursive: true });
  const result = spawnSync(process.execPath, [
    verifyScript, '--subtree', 'build/gateway', '--root', directory, '--work-dir', path.join(directory, 'work')
  ], { cwd: root, encoding: 'utf8' });
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;
  assert.equal(result.status, 2, `an unbundlable root is a toolchain error, not a stale artifact:\n${output}`);
  assert.match(output, /BUILD_FRESHNESS_UNVERIFIABLE/);
  assert.match(output, /src[\\/]gateway[\\/]server\.mjs/, 'the error must name the missing entry');
});

// ── 4c. Defect 2: build/release-notes.md is compared against CHANGELOG.md ──

/** A throwaway root carrying only what the notes check reads. */
function notesRoot(t, { version = '9.9.9', notes, changelog } = {}) {
  const directory = sandbox(t);
  fs.mkdirSync(path.join(directory, 'build'), { recursive: true });
  fs.writeFileSync(path.join(directory, 'package.json'), JSON.stringify({ version }), 'utf8');
  fs.writeFileSync(path.join(directory, 'CHANGELOG.md'),
    changelog ?? `# Changelog\n\n## [${version}] - 2026-01-01\n\n### Added\n- A thing\n\n## [1.0.0] - 2025-01-01\n- old\n`,
    'utf8');
  if (notes !== null) fs.writeFileSync(path.join(directory, 'build', 'release-notes.md'), notes, 'utf8');
  return directory;
}

test('a release-notes.md that does not match CHANGELOG.md is a stale artifact', async (t) => {
  const { verifyReleaseNotes } = await import(pathToFileURL(verifyScript).href);
  // The exact shape of the defect: the notes still describe the PREVIOUS version,
  // and they ship into latest.yml and the GitHub release body.
  const directory = notesRoot(t, { notes: '- old release notes\n' });
  const result = await verifyReleaseNotes({ root: directory, require: true });
  assert.equal(result.ok, false, 'stale notes must fail');
  assert.equal(result.issues[0].kind, 'differs');
  assert.equal(result.subtree, 'build/release-notes.md');
});

test('release-notes.md matching extractReleaseNotes() output passes, byte for byte', async (t) => {
  const { verifyReleaseNotes } = await import(pathToFileURL(verifyScript).href);
  const { extractReleaseNotes } = await import(pathToFileURL(path.join(root, 'scripts', 'release-notes.mjs')).href);
  const changelog = '# Changelog\n\n## [9.9.9] - 2026-01-01\n\n### Added\n- A thing\n';
  const expected = `${extractReleaseNotes(changelog, '9.9.9')}\n`;
  const directory = notesRoot(t, { notes: expected, changelog });
  const result = await verifyReleaseNotes({ root: directory, require: true });
  assert.equal(result.ok, true, JSON.stringify(result.issues));

  // A trailing-newline difference alone must be caught: electron-builder bakes the
  // bytes into latest.yml, so "almost equal" is still the wrong release body.
  fs.writeFileSync(path.join(directory, 'build', 'release-notes.md'), expected.trimEnd(), 'utf8');
  const trimmed = await verifyReleaseNotes({ root: directory, require: true });
  assert.equal(trimmed.ok, false, 'a missing trailing newline is still a difference');
});

test('absent release-notes.md is UNCHECKED by default and a failure when required', async (t) => {
  const { verifyReleaseNotes } = await import(pathToFileURL(verifyScript).href);
  const directory = notesRoot(t, { notes: null });
  // Gitignored (.gitignore:46) and written only by `npm run build:release`, so a
  // clean clone legitimately has none and `npm run build` must still pass.
  const optional = await verifyReleaseNotes({ root: directory });
  assert.equal(optional.ok, true);
  assert.equal(optional.unchecked, true);

  // Where it must exist (the release path generates it), absence is a failure.
  const required = await verifyReleaseNotes({ root: directory, require: true });
  assert.equal(required.ok, false);
  assert.equal(required.issues[0].kind, 'missing-subtree');
});

test('the release-notes verdict is part of the verifier exit status', { timeout: 300_000 }, (t) => {
  // Driven through the CLI, because the requirement is that it changes the EXIT CODE,
  // not just that a helper returns false.
  const directory = sandbox(t);
  const artifact = path.join(directory, 'artifact');
  for (const subtree of ['build/src', 'build/gateway', 'build/renderer']) {
    fs.cpSync(path.join(root, ...subtree.split('/')), path.join(artifact, ...subtree.split('/')), { recursive: true });
  }
  // A clean copy would pass all three subtrees; only the notes are wrong.
  fs.mkdirSync(path.join(artifact, 'build'), { recursive: true });
  fs.writeFileSync(path.join(artifact, 'build', 'release-notes.md'), '- stale notes\n', 'utf8');

  const result = spawnSync(process.execPath, [
    verifyScript,
    '--artifact-root', artifact,
    '--work-dir', path.join(directory, 'work')
  ], { cwd: root, encoding: 'utf8' });
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;

  assert.equal(result.status, 1, `stale notes must fail the whole run:\n${output}`);
  assert.match(output, /BUILD_FRESHNESS_OK 3\/3/, `the subtrees themselves are fresh:\n${output}`);
  assert.match(output, /STALE_BUILD_ARTIFACT build\/release-notes\.md/, output);
});

// ── 4c-bis. Defect 2b: the notes gate is only ARMED by --require-release-notes ──

/**
 * An artifact root holding one real subtree plus a chosen notes state.
 *
 * `--subtree build/gateway` is the only reference emit used, so the CLI path runs in
 * about a second (esbuild only) while still exercising the REAL argument parser and
 * the REAL exit-code wiring — which is the whole point: the flag must change the exit
 * status, not just a helper's return value.
 */
function notesArtifactRoot(t, { notes }) {
  const directory = sandbox(t);
  const artifact = path.join(directory, 'artifact');
  fs.cpSync(path.join(root, 'build', 'gateway'), path.join(artifact, 'build', 'gateway'), { recursive: true });
  if (notes !== null) {
    fs.mkdirSync(path.join(artifact, 'build'), { recursive: true });
    fs.writeFileSync(path.join(artifact, 'build', 'release-notes.md'), notes, 'utf8');
  }
  return { artifact, work: path.join(directory, 'work') };
}

test('--require-release-notes turns an ABSENT notes file into a failing exit, and the flag is what does it', { timeout: 300_000 }, (t) => {
  // THE DEFECT: on a clean runner the gitignored notes file does not exist, the
  // verifier reported BUILD_FRESHNESS_UNCHECKED and exited 0 — so the notes half of
  // the gate was never armed in CI. The flag must be the difference between the two
  // runs on the SAME tree; anything else would mean the gate is armed by accident.
  const { artifact, work } = notesArtifactRoot(t, { notes: null });
  const args = [verifyScript, '--subtree', 'build/gateway', '--artifact-root', artifact, '--work-dir', work];

  const withoutFlag = spawnSync(process.execPath, args, { cwd: root, encoding: 'utf8' });
  const withoutOutput = `${withoutFlag.stdout ?? ''}${withoutFlag.stderr ?? ''}`;
  assert.equal(withoutFlag.status, 0,
    `absent notes without the flag must stay a non-failure (a clean clone must be able to build):\n${withoutOutput}`);
  assert.match(withoutOutput, /BUILD_FRESHNESS_UNCHECKED build\/release-notes\.md/,
    `the unchecked state must be explicit, never silent:\n${withoutOutput}`);

  const withFlag = spawnSync(process.execPath, [...args, '--require-release-notes'], { cwd: root, encoding: 'utf8' });
  const withOutput = `${withFlag.stdout ?? ''}${withFlag.stderr ?? ''}`;
  assert.equal(withFlag.status, 1,
    `the same tree MUST fail once the notes are required:\n${withOutput}`);
  assert.match(withOutput, /STALE_BUILD_ARTIFACT build\/release-notes\.md/, withOutput);
  assert.match(withOutput, /does not exist/, 'the failure must say the file is absent');
  assert.doesNotMatch(withOutput, /BUILD_FRESHNESS_UNCHECKED/,
    `a required-but-absent file must never be reported as merely unchecked:\n${withOutput}`);
});

test('the notes check compares CONTENT, not existence: a same-size edit still fails', { timeout: 300_000 }, async (t) => {
  // The hollow version of this gate is `fs.existsSync`. A file that exists, has the
  // right byte count and the wrong bytes is still the wrong release body, because
  // electron-builder bakes those bytes into latest.yml. Proven at the CLI, with the
  // size deliberately unchanged so only a content comparison can catch it.
  const { verifyReleaseNotes } = await import(pathToFileURL(verifyScript).href);
  const { extractReleaseNotes } = await import(pathToFileURL(path.join(root, 'scripts', 'release-notes.mjs')).href);
  const changelog = fs.readFileSync(path.join(root, 'CHANGELOG.md'), 'utf8');
  const expected = `${extractReleaseNotes(changelog, packageJson.version)}\n`;

  // One character changed, nothing else: same length, same existence, different bytes.
  const firstLetter = expected.search(/[A-Za-z]/);
  assert.ok(firstLetter >= 0, 'the real notes must contain a letter to mutate');
  const mutated = expected.slice(0, firstLetter)
    + (expected[firstLetter] === 'X' ? 'Y' : 'X')
    + expected.slice(firstLetter + 1);
  assert.equal(mutated.length, expected.length, 'the mutation must keep the byte length identical');
  assert.notEqual(mutated, expected);

  const { artifact, work } = notesArtifactRoot(t, { notes: mutated });
  assert.equal(fs.statSync(path.join(artifact, 'build', 'release-notes.md')).size, Buffer.byteLength(expected),
    'the tampered file must be the SAME SIZE as the correct one');

  const result = spawnSync(process.execPath, [
    verifyScript, '--subtree', 'build/gateway', '--artifact-root', artifact, '--work-dir', work, '--require-release-notes'
  ], { cwd: root, encoding: 'utf8' });
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;
  assert.equal(result.status, 1, `a same-size content difference must fail:\n${output}`);
  assert.match(output, /STALE_BUILD_ARTIFACT build\/release-notes\.md/, output);
  // Both sides print the same byte count; only the hashes differ. That is the proof
  // the comparison is not a size or existence check.
  assert.match(output, /differs\s+release-notes\.md disk=(\d+) B sha256=(\w{12})… fresh=\1 B sha256=(\w{12})…/,
    `the report must show equal sizes with differing hashes:\n${output}`);

  // And the helper agrees on the same fixture, so the CLI result is not a fluke.
  const direct = await verifyReleaseNotes({ root, artifactRoot: artifact, require: true });
  assert.equal(direct.ok, false);
  assert.equal(direct.issues[0].kind, 'differs');
});

// ── 4d. Defect 3: app.asar is compared against build/ ──────────────────────

/**
 * Pack a copy of the real shipped subtrees into an archive, optionally damaging one
 * file first. The REAL dist/ is never touched: this only reads build/.
 *
 * `build/src/main` is copied whole (including the .d.ts files tsc emits) on purpose:
 * electron-builder strips `d.ts` (app-builder-lib fileMatcher.js:19 `excludedExts`)
 * and `*.map` (electron-builder.yml), so a faithful staging directory contains files
 * the packager filters out — and the check must not mistake those for stale entries.
 */
async function makeAsar(t, { tamper, extra } = {}) {
  const asar = createRequire(path.join(root, 'package.json'))('@electron/asar');
  const directory = sandbox(t);
  const staging = path.join(directory, 'staging');
  for (const subtree of ['build/gateway', 'build/src/main', 'build/src/preload', 'build/renderer']) {
    fs.cpSync(path.join(root, ...subtree.split('/')), path.join(staging, ...subtree.split('/')), { recursive: true });
  }
  if (tamper) tamper(staging);
  if (extra) fs.writeFileSync(path.join(staging, ...extra.split('/')), 'stale bundle', 'utf8');
  const archivePath = path.join(directory, 'app.asar');
  await asar.createPackage(staging, archivePath);
  return archivePath;
}

test('the packaged asar passes when it matches build/', { timeout: 120_000 }, async (t) => {
  const { verifyPackagedAsar } = await import(pathToFileURL(verifyScript).href);
  const archivePath = await makeAsar(t);
  const result = verifyPackagedAsar({ root, asarPath: archivePath });
  assert.equal(result.ok, true, JSON.stringify(result.issues.slice(0, 5)));
  assert.ok(result.fresh.fileCount > 40, 'the gateway, main modules and renderer assets must all be compared');
});

test('a stale engine inside the packaged asar is detected', { timeout: 120_000 }, async (t) => {
  // THE DEFECT this closes: measured on this tree, app.asar was 03:28 while the
  // sources were 03:51, and every check above still passed because they all compare
  // build/ to the sources and none compares what the user runs.
  const { verifyPackagedAsar } = await import(pathToFileURL(verifyScript).href);
  const archivePath = await makeAsar(t, {
    tamper: (staging) => {
      const file = path.join(staging, 'build', 'gateway', 'server.mjs');
      fs.writeFileSync(file, fs.readFileSync(file, 'utf8').replace('no reasoning output observed', 'stale'), 'utf8');
    }
  });
  const result = verifyPackagedAsar({ root, asarPath: archivePath });
  assert.equal(result.ok, false, 'a stale engine in the archive must fail');
  const issue = result.issues.find((candidate) => candidate.relative === 'build/gateway/server.mjs');
  assert.ok(issue, `the failure must name the entry, got ${JSON.stringify(result.issues.slice(0, 3))}`);
  assert.equal(issue.kind, 'differs');
});

test('a main-process module missing from the asar is detected', { timeout: 120_000 }, async (t) => {
  const { verifyPackagedAsar } = await import(pathToFileURL(verifyScript).href);
  const archivePath = await makeAsar(t, {
    tamper: (staging) => fs.rmSync(path.join(staging, 'build', 'src', 'main', 'index.js'))
  });
  const result = verifyPackagedAsar({ root, asarPath: archivePath });
  assert.equal(result.ok, false);
  const issue = result.issues.find((candidate) => candidate.relative === 'build/src/main/index.js');
  assert.ok(issue, 'the entry package.json#main names must be required');
  assert.equal(issue.kind, 'missing');
});

test('an orphaned renderer bundle left in the asar is detected', { timeout: 120_000 }, async (t) => {
  // The realistic stale shape: the previous content-hashed bundle survives in the
  // archive while the current build emits a different name.
  const { verifyPackagedAsar } = await import(pathToFileURL(verifyScript).href);
  const archivePath = await makeAsar(t, { extra: 'build/renderer/assets/index-BPrMadS9.js' });
  const result = verifyPackagedAsar({ root, asarPath: archivePath });
  assert.equal(result.ok, false);
  const issue = result.issues.find((candidate) => candidate.relative === 'build/renderer/assets/index-BPrMadS9.js');
  assert.ok(issue, 'an entry the current build does not produce must be reported');
  assert.equal(issue.kind, 'extra');
});

// ── 4d-bis. Defect 3b: build/src/preload/ is shipped and must be compared ───

test('an orphan left in build/src/preload/ inside the asar is detected', { timeout: 120_000 }, async (t) => {
  // THE DEFECT: electron-builder.yml:9 ships `build/src/preload/**/*`, but
  // ASAR_COMPARED_PREFIXES did not list it. Only the one required `index.js` was
  // read from that directory, so any OTHER entry in it was invisible.
  // MEASURED BEFORE THE FIX: packing `build/src/preload/stale-orphan.js` into an
  // otherwise current archive printed ASAR_FRESHNESS_VERIFIED and exited 0.
  const { verifyPackagedAsar, ASAR_COMPARED_PREFIXES } = await import(pathToFileURL(verifyScript).href);
  assert.ok(ASAR_COMPARED_PREFIXES.includes('build/src/preload/'),
    'the shipped preload directory must be in the compared prefixes');

  const archivePath = await makeAsar(t, { extra: 'build/src/preload/stale-orphan.js' });
  const result = verifyPackagedAsar({ root, asarPath: archivePath });
  assert.equal(result.ok, false,
    'a stale orphan in the shipped preload directory must fail the asar check');
  const issue = result.issues.find((candidate) => candidate.relative === 'build/src/preload/stale-orphan.js');
  assert.ok(issue, `the failure must name the orphan, got ${JSON.stringify(result.issues.slice(0, 3))}`);
  assert.equal(issue.kind, 'extra');
});

test('a stale preload bridge inside the asar is detected', { timeout: 120_000 }, async (t) => {
  // Not just orphans: the required entry itself is byte-compared. The preload is the
  // only channel between renderer and main, so a stale one is a real shipped defect.
  const { verifyPackagedAsar } = await import(pathToFileURL(verifyScript).href);
  const archivePath = await makeAsar(t, {
    tamper: (staging) => {
      const file = path.join(staging, 'build', 'src', 'preload', 'index.js');
      fs.appendFileSync(file, '\n// stale bridge\n', 'utf8');
    }
  });
  const result = verifyPackagedAsar({ root, asarPath: archivePath });
  assert.equal(result.ok, false);
  const issue = result.issues.find((candidate) => candidate.relative === 'build/src/preload/index.js');
  assert.ok(issue, 'the shipped preload bridge must be compared byte for byte');
  assert.equal(issue.kind, 'differs');
});

test('a missing archive exits 2, not 1: nothing was packaged, nothing is stale', { timeout: 120_000 }, (t) => {
  const directory = sandbox(t);
  const result = spawnSync(process.execPath, [
    verifyScript, '--asar', '--asar-path', path.join(directory, 'nope', 'app.asar')
  ], { cwd: root, encoding: 'utf8' });
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;
  assert.equal(result.status, 2, `a missing archive is a toolchain problem:\n${output}`);
  assert.match(output, /BUILD_FRESHNESS_UNVERIFIABLE/);
  assert.match(output, /npm run package:dir/, 'the error must say how to produce the archive');
});

// ── 4e. Defect 5: the tsc reference emit asserts its layout ────────────────

test('the tsc reference emit asserts rootDir and a non-empty src/main', async (t) => {
  const { assertTypeScriptLayout } = await import(pathToFileURL(verifyScript).href);
  const directory = sandbox(t);
  const outDir = path.join(directory, 'tsc');
  fs.mkdirSync(path.join(outDir, 'src', 'main'), { recursive: true });
  fs.writeFileSync(path.join(outDir, 'src', 'main', 'index.js'), 'module.exports = {};', 'utf8');
  fs.writeFileSync(path.join(outDir, 'vite.config.js'), 'module.exports = {};', 'utf8');

  // The normal layout returns the subtree the comparison must use.
  assert.equal(assertTypeScriptLayout(outDir), path.join(outDir, 'src'));

  // An include/rootDir change that moves the emit one level down must be a clear
  // TOOLCHAIN error (exit 2), not a mass of "missing" files (a false positive that
  // accuses a correct build) and not a silent empty comparison.
  const moved = path.join(directory, 'moved');
  fs.mkdirSync(path.join(moved, 'nested', 'src', 'main'), { recursive: true });
  fs.writeFileSync(path.join(moved, 'nested', 'src', 'main', 'index.js'), '', 'utf8');
  assert.throws(() => assertTypeScriptLayout(moved), /rootDir/,
    'a moved emit must be reported as a rootDir layout problem');

  // And an emit that produced nothing must not be silently compared as empty.
  const empty = path.join(directory, 'empty');
  fs.mkdirSync(empty, { recursive: true });
  assert.throws(() => assertTypeScriptLayout(empty), /src[\\/]main[\\/]index\.js/);
});

// ── 5. A broken toolchain is not reported as a stale artifact ──────────────

test('the verifier exits 2, not 1, when it cannot produce a reference emit', { timeout: 120_000 }, (t) => {
  const directory = sandbox(t);
  // A root with no node_modules cannot resolve tsc/vite: that is a toolchain
  // failure, and reporting it as "stale" would send someone to rebuild needlessly.
  fs.mkdirSync(path.join(directory, 'build', 'src'), { recursive: true });
  const result = spawnSync(process.execPath, [
    verifyScript, '--root', directory, '--work-dir', path.join(directory, 'work')
  ], { cwd: root, encoding: 'utf8' });
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`;
  assert.equal(result.status, 2, `an unbuildable reference must exit 2:\n${output}`);
  assert.match(output, /BUILD_FRESHNESS_UNVERIFIABLE/);
});
